Add `themeSchema = z.enum(['light', 'dark', 'system'])`, `Theme = z.infer<typeof themeSchema>`, `settingsSchema = z.object({ theme: themeSchema })`, `Settings = z.infer<typeof settingsSchema>`, maybe `UserSettings` for DB.

`server/src/services/settings.ts`:
```typescript
import { z } from 'zod'
import { prisma } from '@/lib/prisma'

const themeSchema = z.enum(['light', 'dark', 'system'])

export const updateSettingsSchema = z.object({
  theme: themeSchema,
})

export type Theme = z.infer<typeof themeSchema>

export async function getSettings(userId: string) {
  const settings = await prisma.userSettings.findUnique({ where: { userId } })
  return { theme: settings?.theme || 'system' }
}

export async function updateSettings(userId: string, input: unknown) {
  const parsed = updateSettingsSchema.safeParse(input)
  if (!parsed.success) {
    throw new Error(parsed.error.errors[0].message)
  }
  await prisma.userSettings.upsert({
    where: { userId },
    create: { userId, theme: parsed.data.theme },
    update: { theme: parsed.data.theme },
  })
  return { theme: parsed.data.theme }
}
```

`server/src/routes/settings.ts`:
```typescript
import { Request, Response, NextFunction, Router } from 'express'
import { requireAuth } from '@/middleware/auth'
import { getSettings, updateSettings } from '@/services/settings'

const router = Router()

type AsyncHandler = ...

router.get('/', requireAuth, asyncRoute(async (req, res) => {
  const settings = await getSettings(req.user!.id)
  res.json({ settings })
}))

router.put('/', requireAuth, asyncRoute(async (req, res) => {
  try {
    const settings = await updateSettings(req.user!.id, req.body)
    res.json({ settings })
  } catch (e) {
    res.status(400).json({ error: e instanceof Error ? e.message : '잘못된 요청입니다.' })
  }
}))

export default router
```

