`client/src/stores/theme.ts`:
```typescript
import { create } from 'zustand'
import { persist } from 'zustand/middleware'  // or manual

type Theme = 'light' | 'dark' | 'system'

interface ThemeState {
  theme: Theme
  systemTheme: 'light' | 'dark'
  setTheme: (theme: Theme) => void
  setSystemTheme: (theme: 'light' | 'dark') => void
  resolvedTheme: 'light' | 'dark'
}

const STORAGE_KEY = 'wellness-theme'

function getSystemTheme(): 'light' | 'dark' {
  if (typeof window === 'undefined') return 'light'
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

export const useTheme = create<ThemeState>()(
  persist(
    (set, get) => ({
      theme: 'system',
      systemTheme: getSystemTheme(),
      setTheme: (theme) => set({ theme }),
      setSystemTheme: (systemTheme) => set({ systemTheme }),
      get resolvedTheme() {
        const { theme, systemTheme } = get()
        return theme === 'system' ? systemTheme : theme
      },
    }),
    {
      name: STORAGE_KEY,
      partialize: (state) => ({ theme: state.theme }),
    },
  ),
)
```

Hmm, but `resolvedTheme` as a getter in Zustand state is tricky. In Zustand, state should be serializable. A getter might not be reactive. Better to have a function or selector outside. Let me keep the store simple:

```typescript
import { create } from 'zustand'
import { persist } from 'zustand/middleware'

export type Theme = 'light' | 'dark' | 'system'
export type ResolvedTheme = 'light' | 'dark'

interface ThemeState {
  theme: Theme
  setTheme: (theme: Theme) => void
}

export const useTheme = create<ThemeState>()(
  persist(
    (set) => ({
      theme: 'system',
      setTheme: (theme) => set({ theme }),
    }),
    { name: 'wellness-theme' },
  ),
)
```

But I need `systemTheme` and resolution in the ThemeProvider. The store itself doesn't need resolved theme. The ThemeProvider can compute it. But the Header might want to know the current mode to display icon. The Header can use `useTheme` to get `theme` and optionally compute resolved.

