import { z } from 'zod'
import { prisma } from '@/lib/prisma'

// DB에 저장되는 테마 값
export const themeSchema = z.enum(['light', 'dark', 'system'])

export type Theme = z.infer<typeof themeSchema>

export const updateSettingsSchema = z.object({
  theme: themeSchema,
})

export interface UserSettings {
  theme: Theme
}

/**
 * 사용자 설정을 조회합니다. 설정이 없으면 기본값 'system'을 반환합니다.
 */
export async function getSettings(userId: string): Promise<UserSettings> {
  const settings = await prisma.userSettings.findUnique({
    where: { userId },
    select: { theme: true },
  })
  return { theme: (settings?.theme as Theme) ?? 'system' }
}

/**
 * 테마 설정을 업데이트하거나 새로 생성합니다.
 */
export async function updateSettings(
  userId: string,
  input: unknown,
): Promise<UserSettings> {
  const parsed = updateSettingsSchema.safeParse(input)
  if (!parsed.success) {
    throw new Error(parsed.error.errors[0].message)
  }

  const { theme } = parsed.data
  await prisma.userSettings.upsert({
    where: { userId },
    create: { userId, theme },
    update: { theme },
  })

  return { theme }
}

import { Request, Response, NextFunction, Router } from 'express'
import { requireAuth } from '@/middleware/auth'
import { getSettings, updateSettings } from '@/services/settings'

type AsyncHandler = (req: Request, res: Response, _next: NextFunction) => Promise<void>

function asyncRoute(handler: AsyncHandler) {
  return (req: Request, res: Response, next: NextFunction) => {
    handler(req, res, next).catch(next)
  }
}

const router = Router()

router.get(
  '/',
  requireAuth,
  asyncRoute(async (req, res) => {
    const settings = await getSettings(req.user!.id)
    res.json({ settings })
  }),
)

router.put(
  '/',
  requireAuth,
  asyncRoute(async (req, res) => {
    try {
      const settings = await updateSettings(req.user!.id, req.body)
      res.json({ settings })
    } catch (e) {
      const message = e instanceof Error ? e.message : '잘못된 요청입니다.'
      res.status(400).json({ error: message })
    }
  }),
)

export default router

