import { useEffect, useState } from 'react'
import { useTheme } from '@/stores/theme'
import { useSettings } from '@/api/settings'
import { useAuth } from '@/stores/auth'
import type { Theme } from '@/types/schemas'

function getSystemTheme(): 'light' | 'dark' {
  if (typeof window === 'undefined') return 'light'
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

function resolveTheme(theme: Theme, system: 'light' | 'dark'): 'light' | 'dark' {
  return theme === 'system' ? system : theme
}

interface ThemeProviderProps {
  children: React.ReactNode
}

export function ThemeProvider({ children }: ThemeProviderProps) {
  const theme = useTheme((state) => state.theme)
  const setTheme = useTheme((state) => state.setTheme)
  const [systemTheme, setSystemTheme] = useState<'light' | 'dark'>(getSystemTheme)
  const user = useAuth((state) => state.user)
  const { data: settings } = useSettings()

  // 시스템 테마 변경 감지
  useEffect(() => {
    const media = window.matchMedia('(prefers-color-scheme: dark)')
    const listener = (e: MediaQueryListEvent) => setSystemTheme(e.matches ? 'dark' : 'light')
    media.addEventListener('change', listener)
    return () => media.removeEventListener('change', listener)
  }, [])

  // 서버 설정을 최초 로드하면 로컬 상태에 반영
  useEffect(() => {
    if (settings?.theme && user) {
      setTheme(settings.theme)
    }
  }, [settings, setTheme, user])

  // html 요소에 dark/light 클래스 적용
  useEffect(() => {
    const effective = resolveTheme(theme, systemTheme)
    document.documentElement.classList.remove('light', 'dark')
    document.documentElement.classList.add(effective)
  }, [theme, systemTheme])

  return <>{children}</>
}

import { Sun, Moon, Monitor } from 'lucide-react'
import { useTheme } from '@/stores/theme'
import { useAuth } from '@/stores/auth'
import { useUpdateSettings } from '@/api/settings'
import type { Theme } from '@/types/schemas'

const THEMES: Theme[] = ['light', 'dark', 'system']

function getNextTheme(current: Theme): Theme {
  const index = THEMES.indexOf(current)
  return THEMES[(index + 1) % THEMES.length]
}

function getThemeIcon(theme: Theme) {
  if (theme === 'dark') return <Moon className="h-5 w-5" />
  if (theme === 'light') return <Sun className="h-5 w-5" />
  return <Monitor className="h-5 w-5" />
}

function getThemeLabel(theme: Theme): string {
  if (theme === 'dark') return '다크 모드'
  if (theme === 'light') return '라이트 모드'
  return '시스템 설정'
}

export function Header() {
  const theme = useTheme((state) => state.theme)
  const setTheme = useTheme((state) => state.setTheme)
  const user = useAuth((state) => state.user)
  const { mutate: updateSettings } = useUpdateSettings()

  const handleToggle = () => {
    const next = getNextTheme(theme)
    setTheme(next)
    if (user) {
      updateSettings(next)
    }
  }

