    useTheme.setState({ theme: 'system' })

    render(
      <ThemeProvider>
        <div />
      </ThemeProvider>,
      { wrapper },
    )

    await waitFor(() => {
      expect(document.documentElement.classList.contains('dark')).toBe(true)
    })
