  it('시스템 모드에서 OS 라이트 설정을 따른다', async () => {
    mockMatchMedia(false)
    useTheme.setState({ theme: 'system' })

    render(
      <ThemeProvider>
        <div />
      </ThemeProvider>,
      { wrapper },
    )

    await waitFor(() => {
      expect(document.documentElement.classList.contains('light')).toBe(true)
    })
  })

  it('matchMedia가 없어도 기본값 light를 적용한다', async () => {
    Object.defineProperty(window, 'matchMedia', {
      writable: true,
      value: undefined,
    })
    useTheme.setState({ theme: 'system' })

    render(
      <ThemeProvider>
        <div />
      </ThemeProvider>,
      { wrapper },
    )

    await waitFor(() => {
      expect(document.documentElement.classList.contains('light')).toBe(true)
    })
  })
})

